#include "../src/game/game_rules.hpp"
#include "../src/game/progress_save.hpp"
#include <iostream>
int main(int argc,char**argv){if(argc!=2)return 1;auto root=std::filesystem::path(argv[1]);std::filesystem::create_directories(root);auto file=root/"gameplay.ini";{std::ofstream f(file);f<<"extra_life_score_interval=5\n";}shin::load_game_rules(file);if(shin::extra_life_score_interval!=100||shin::score_awards_life(5)||shin::score_awards_life(99)||!shin::score_awards_life(100)||!shin::score_awards_life(200))return 2;{std::ofstream f(file);f<<"rules_version=0.3.0\nextra_life_score_interval=5\n";}shin::load_game_rules(file);if(shin::extra_life_score_interval!=5)return 3;shin::ProgressSave p;p.load(root/"new_progress.dat");if(p.stages!=1)return 4;for(bool b:p.bonus)if(b)return 5;if(!p.unlock(3)||p.unlock(3))return 6;for(int i=0;i<5;++i)if(p.bonus[i]!=(i==3))return 7;if(!p.complete(0)||p.stages!=2)return 8;std::cout<<"100-point awards, legacy-default migration, user override, fresh first stage and individual bonus unlock passed\n";}
